                      if (find_rep(2'd1) != find_rep(2'd3)) begin\n                                        parent[find_rep(2'd1)] <= find_rep(2'd3);\n                                    end\n                                end\n                                3'd5: begin // (2,3)\n                                    if (find_rep(2'd2) != find_rep(2'd3)) begin\n                                        parent[find_rep(2'd2)] <= find_rep(2'd3);\n                                    end\n                                end\n                            endcase\n                            added_edges_mask[sorted_indices[k]] <= 1'b1;\n                        end\n                        k <= k + 3'd1;\n                    end else begin\n                        // Done adding edges for this threshold\n                        city_idx <= 2'd0;\n                        state <= FIND_COMPONENTS;\n                    end\n                end\n\n                FIND_COMPONENTS: begin\n                    // sub_step 0: Find root of city_idx. sub_step 1: Build mask.\n                    if (sub_step == 2'd0) begin\n                        if (city_idx < num_nodes) begin\n                            if (find_rep(city_idx) == city_idx) begin\n                                // Found a component root\n                                component_mask <= 4'd0;\n                                accum_idx <= 2'd0;\n                                sub_step <= 2'd1;\n                            end else begin\n                                city_idx <= city_idx + 2'd1;\n                            end\n                        end else begin\n                            // No more components found for this threshold\n                            state <= UPDATE_RESULT;\n                            sub_step <= 2'd0;\n                        end\n                    end else if (sub_step == 2'd1) begin\n                        // Build component mask\n                        if (accum_idx < num